CREATE SCHEMA IF NOT EXISTS data_public;
SET search_path TO data_public, public;

CREATE TABLE IF NOT EXISTS data_public.статус (
    status_id SERIAL PRIMARY KEY,
    clsname VARCHAR(100) NOT NULL,
    clspaint VARCHAR(50) NOT NULL
);

CREATE TABLE IF NOT EXISTS data_public.арендаторы (
    rentor_id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    phone VARCHAR(20),
    email VARCHAR(255),
    inn VARCHAR(12)
);

CREATE TABLE IF NOT EXISTS data_public.справочник_объектов_недвижимости (
    objectestate_id SERIAL PRIMARY KEY,
    cadastral_number VARCHAR(50) UNIQUE,
    name VARCHAR(255) NOT NULL,
    address TEXT,
    object_type VARCHAR(100),
    total_area NUMERIC(15,2),
    width NUMERIC(10,8),
    length NUMERIC(11,8),
    status_id INTEGER REFERENCES data_public.статус(status_id)
);

CREATE TABLE IF NOT EXISTS data_public.договор_аренды (
    lease_id SERIAL PRIMARY KEY,
    object_id INTEGER REFERENCES data_public.справочник_объектов_недвижимости(objectestate_id),
    rentor_id INTEGER REFERENCES data_public.арендаторы(rentor_id),
    contract_number VARCHAR(100),
    status_contract VARCHAR(100),
    date_start DATE,
    date_end DATE,
    date_pay DATE,
    rent NUMERIC(15,2),
    rented_area NUMERIC(15,2),
    name VARCHAR(255)
);

CREATE TABLE IF NOT EXISTS data_public.платежи (
    pay_id SERIAL PRIMARY KEY,
    lease_id INTEGER REFERENCES data_public.договор_аренды(lease_id),
    sum NUMERIC(15,2),
    date_pay DATE,
    status_pay VARCHAR(50),
    zipdate TIMESTAMP WITH TIME ZONE,
    ziplastdate TIMESTAMP WITH TIME ZONE,
    zipoper SMALLINT,
    ziplastuser VARCHAR(255),
    zipuser VARCHAR(255),
    zipvers SMALLINT,
    name VARCHAR(255)
);

CREATE TABLE IF NOT EXISTS data_public.уведомления (
    notification_id SERIAL PRIMARY KEY,
    lease_id INTEGER,
    object_id INTEGER,
    notification_type VARCHAR(50),
    message TEXT,
    creation_date DATE,
    status_notification VARCHAR(50),
    name VARCHAR(255),
    days_relative INTEGER,
    due_date DATE,
    sum NUMERIC(15,2),
    contract_number VARCHAR(255),
    cadastral_number VARCHAR(255),
    zipdate TIMESTAMP WITH TIME ZONE,
    ziplastdate TIMESTAMP WITH TIME ZONE,
    zipoper SMALLINT,
    ziplastuser VARCHAR(255),
    zipuser VARCHAR(255),
    zipvers SMALLINT
);









CREATE INDEX IF NOT EXISTS idx_objects_cadastral ON data_public.справочник_объектов_недвижимости(cadastral_number);
CREATE INDEX IF NOT EXISTS idx_payments_lease ON data_public.платежи(lease_id);
CREATE INDEX IF NOT EXISTS idx_payments_date ON data_public.платежи(date_pay);
CREATE INDEX IF NOT EXISTS idx_payments_status ON data_public.платежи(status_pay);
CREATE INDEX IF NOT EXISTS idx_contracts_object ON data_public.договор_аренды(object_id);
CREATE INDEX IF NOT EXISTS idx_contracts_rentor ON data_public.договор_аренды(rentor_id);
CREATE INDEX IF NOT EXISTS idx_notifications_lease ON data_public.уведомления(lease_id);
CREATE INDEX IF NOT EXISTS idx_notifications_status ON data_public.уведомления(status_notification);